                       ('Bottom', g.switch(belongs_a, outer_a, outer_b, 'VECTOR')),
                       ('Cut Top', g.switch(belongs_a, cut_b, cut_a, 'VECTOR')),
                       ('Cut Bottom', g.switch(belongs_a, cut_a, cut_b, 'VECTOR')),
