    nx_raw = g.math('MAXIMUM', 1., g.math('CEIL', g.math('DIVIDE', g.math('MAXIMUM', depth_a, depth_b), inp.outputs['Cell Size'])))
    target = g.math('MINIMUM', inp.outputs['Cell Size'], g.math('DIVIDE', g.math('MINIMUM', depth_a, depth_b), nx_raw))
