        order = g.node('GeometryNodeSortElements', 'Regular cap exact body cut ordering'); order.domain = 'POINT'
        g.set(seam, order.inputs['Geometry']); g.set(station, order.inputs['Sort Weight'])
        regular_seam = order.outputs['Geometry']; seam_count = bridge._size(g, regular_seam)
