        world_mesh = bridge._position(g, result, g.switch(pinned, world, original_xy, 'VECTOR'))
        valid = g.all(valid, seam_frame_ok, g.compare(inverse_error, bridge.TOLERANCE, 'LESS_EQUAL'),
                      step.shape_good(g, world_mesh))
